/**
 * Equirectangular project lat/lon onto world-map.svg (viewBox 0 0 1000 500).
 */
window.fpProjectWorld = function fpProjectWorld(lat, lon, w, h) {
  w = w || 1000;
  h = h || 500;
  const x = ((Number(lon) + 180) / 360) * w;
  const y = ((90 - Number(lat)) / 180) * h;
  if (!Number.isFinite(x) || !Number.isFinite(y)) return null;
  return {
    x: Math.max(8, Math.min(w - 8, x)),
    y: Math.max(8, Math.min(h - 8, y)),
  };
};
